def number_existing_downloads(apps, schema_editor):
    artifacts = apps.get_model("library", "ExportArtifact").objects.using(
        schema_editor.connection.alias
    )
    for artifact in artifacts.all().iterator():
        basename = artifact.filename.removesuffix(".epub")
        artifact.filename = f"{basename}_v1.epub"
        artifact.save(update_fields=["filename"])


